head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF00006";
scwin.chrg_tel_no = undefined;
scwin.encryp_cellphone_no = undefined;
scwin.chrg_fax_no = undefined;
scwin.cntr_cd = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.cntr_cd = '' + dma_map.get("cntrIsoCd") + '';
        scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf00006.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_IsurMessage", fn: function () { return String(String((dma_pageContext.get("message") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        if ($c.util.getComponent('dma_searchMemberReq').get('IsurNewYn') === "Y") {
            $c.util.getComponent("txt_joinMember").show();
            $c.util.getComponent("joinMember1").show();
            $c.util.getComponent("joinMember2").show();
            $c.util.getComponent("joinMember3").show();
        } else {
            $c.util.getComponent("txt_joinMember").hide();
            $c.util.getComponent("joinMember1").hide();
            $c.util.getComponent("joinMember2").hide();
            $c.util.getComponent("joinMember3").hide();
        }
        fn_startBlink();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_startBlink — as-is 공통(폼 전역 의존) — 반입 보류

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf00006.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
