///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchMember
 * @description search Member 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchMember = async function () {
    const sbmOptions = {
        id: "tx_fn_searchMember",
        method: "post",
        action: "/corp/register.do?method=searchMember",
        ref: "dma_searchMemberReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_registerMember
 * @description register Member 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_registerMember = async function () {
    const sbmOptions = {
        id: "tx_fn_registerMember",
        method: "post",
        action: "/corp/register.do?method=registerMember",
        ref: "dma_registerMemberReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_checkUsrId
 * @description check Usr Id 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_checkUsrId = async function () {
    const sbmOptions = {
        id: "tx_fn_checkUsrId",
        method: "post",
        action: "/corp/register.do?method=searchUsrId",
        ref: "dma_checkUsrIdReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name emailCheck
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.emailCheck = function (obj) { try { const t = (obj && obj.value != null) ? obj : ((obj && (obj.target || obj.srcElement)) || null); if (t && t.value != null) { t.value = String(t.value).replace(/[^A-Za-z0-9.@_%+\\-]/g, ''); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

/**
 * @method
 * @name searchMember
 * @description search Member 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchMember = async function () {
    const vIsurCd = $c.util.getComponent('ipt_isurCd').getValue().replace(/ /gi, "");
    if ($c.str.getByteLength(vIsurCd) === 0) {
        await $c.win.alert("발행기관코드를 입력하십시오.");
        $c.util.getComponent("ipt_isurCd").setValue("");
        $c.util.getComponent("ipt_isurCd").focus();
        return false;
    } else {
        if (vIsurCd.substring(0, 1) === "#") {
            await $c.win.alert("임시발행기관코드는 신청할 수 없습니다.");
            $c.util.getComponent("ipt_isurCd").setValue("");
            $c.util.getComponent("ipt_isurCd").focus();
            return false;
        } else {
            if (vIsurCd.length < 5) {
                await $c.win.alert("발행기관코드 5자리를 입력하십시오.");
                $c.util.getComponent("ipt_isurCd").setValue("");
                $c.util.getComponent("ipt_isurCd").focus();
                return false;
            } else {
                await scwin.tx_fn_searchMember();
            }
        }
    }
};

/**
 * @method
 * @name enterEvent
 * @description enter Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.enterEvent = async function (e) {
    if (e.keyCode === 13) {
        await scwin.searchMember();
        return false;
    } else {
        $c.util.getComponent('dma_searchMemberReq').set('IsurNewYn', "");
        $c.util.getComponent("ipt_IsurMessage").setValue("");
        return true;
    }
};

/**
 * @method
 * @name changeId
 * @description change Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeId = function () {
    const oldIdVal = $c.util.getComponent("dma_searchMemberReq").get("oldIntegUsrId").replace(/ /gi, "");
    if (oldIdVal !== "") {
        $c.util.getComponent('ipt_message').setValue("");
        $("input[name='newYn']").val("");
    }
    return true;
};

/**
 * @method
 * @name dataValidation
 * @description data Validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataValidation = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_isurCd').getValue()) === 0) {
        await $c.win.alert("발행기관코드를 입력하십시오.");
        $c.util.getComponent("ipt_isurCd").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_isurCd').getValue()) < 5) {
        await $c.win.alert("발행기관코드를 확인하십시오.");
        $c.util.getComponent("ipt_isurCd").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('dma_searchMemberReq').get('IsurNewYn')) === 0) {
        await $c.win.alert("발행기관코드를 조회하십시오.");
        $c.util.getComponent("ipt_isurCd").focus();
        return false;
    } else {
        if ($c.util.getComponent('dma_searchMemberReq').get('IsurNewYn') !== "Y") {
            await $c.win.alert($c.util.getComponent('ipt_IsurMessage').getValue());
            $c.util.getComponent("ipt_isurCd").setValue("");
            $c.util.getComponent("ipt_isurCd").focus();
            return false;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_integUsrId').getValue()) === 0) {
        await $c.win.alert("아이디를 입력하십시오.");
        $c.util.getComponent("ipt_integUsrId").focus();
        return false;
    } else {
        if ($c.str.getByteLength($c.util.getComponent('dma_searchMemberReq').get('newYn')) === 0) {
            await $c.win.alert("아이디 중복확인 여부를 확인하십시오.");
            $c.util.getComponent("ipt_integUsrId").focus();
            return false;
        } else {
            if ($c.util.getComponent('dma_searchMemberReq').get('newYn') !== "Y") {
                await $c.win.alert("다른 아이디를 입력하십시오.");
                $c.util.getComponent("ipt_integUsrId").focus();
                return false;
            }
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_chrgNm').getValue()) === 0) {
        await $c.win.alert("담당자이름을 입력하세요.");
        $c.util.getComponent("ipt_chrgNm").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_belngDepNm').getValue()) === 0) {
        await $c.win.alert("소속부서를 입력하세요.");
        $c.util.getComponent("ipt_belngDepNm").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_jobtitlNm').getValue()) === 0) {
        await $c.win.alert("직책을 입력하세요.");
        $c.util.getComponent("ipt_jobtitlNm").focus();
        return false;
    }
    if ($c.util.getComponent("dma_searchMemberReq").get("cntrCd") === '410') {
        if ($c.str.getByteLength($c.util.getComponent('ipt_chrgTelNo1').getValue()) === 0) {
            await $c.win.alert("담당자 전화번호를 입력하세요.");
            $c.util.getComponent("ipt_chrgTelNo1").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_chrgTelNo2').getValue()) === 0) {
            await $c.win.alert("담당자 전화번호를 입력하세요.");
            $c.util.getComponent("ipt_chrgTelNo2").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_chrgTelNo3').getValue()) === 0) {
            await $c.win.alert("담당자 전화번호를 입력하세요.");
            $c.util.getComponent("ipt_chrgTelNo3").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo1').getValue()) === 0) {
            await $c.win.alert("담당자 휴대전화번호를 입력하세요.");
            $c.util.getComponent("ipt_encrypCellphoneNo1").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo2').getValue()) === 0) {
            await $c.win.alert("담당자 휴대전화번호를 입력하세요.");
            $c.util.getComponent("ipt_encrypCellphoneNo2").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo3').getValue()) === 0) {
            await $c.win.alert("담당자 휴대전화번호를 입력하세요.");
            $c.util.getComponent("ipt_encrypCellphoneNo3").focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_chrgFaxNo1').getValue()) > 0 || $c.str.getByteLength($c.util.getComponent('ipt_chrgFaxNo2').getValue()) > 0 || $c.str.getByteLength($c.util.getComponent('ipt_chrgFaxNo3').getValue()) > 0) {
            if ($c.str.getByteLength($c.util.getComponent('ipt_chrgFaxNo1').getValue()) === 0) {
                await $c.win.alert("담당자 팩스번호를 입력하세요.");
                $c.util.getComponent("ipt_chrgFaxNo1").focus();
                return false;
            }
            if ($c.str.getByteLength($c.util.getComponent('ipt_chrgFaxNo2').getValue()) === 0) {
                await $c.win.alert("담당자 팩스번호를 입력하세요.");
                $c.util.getComponent("ipt_chrgFaxNo2").focus();
                return false;
            }
            if ($c.str.getByteLength($c.util.getComponent('ipt_chrgFaxNo3').getValue()) === 0) {
                await $c.win.alert("담당자 팩스번호를 입력하세요.");
                $c.util.getComponent("ipt_chrgFaxNo3").focus();
                return false;
            }
        }
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_encrypCellphoneNo').getValue()) === 0) {
            await $c.win.alert("담당자 휴대전화번호를 입력하세요.");
            scwin.encryp_cellphone_no.focus();
            return false;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_chrgTelNo').getValue()) === 0) {
            await $c.win.alert("담당자 전화번호를 입력하세요.");
            scwin.chrg_tel_no.focus();
            return false;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail1').getValue()) === 0) {
        await $c.win.alert("회사담당자 이메일을 입력하세요.");
        $c.util.getComponent("ipt_encrypChrgEmail1").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail2').getValue()) === 0) {
        await $c.win.alert("회사담당자 이메일을 입력하세요.");
        $c.util.getComponent("ipt_encrypChrgEmail2").focus();
        return false;
    }
    if (document.infoIframe.getComponentById("perInfo1").checked === false) {
        await $c.win.alert("개인정보 처리방침에 동의해 주세요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if (document.infoIframe.getComponentById("perInfo2").checked === false) {
        await $c.win.alert("개인정보 수집 및 이용에 동의해 주세요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    }
    if (document.infoIframe.getComponentById("perInfo3").checked === false) {
        await $c.win.alert("표준코드 부여 및 관리 서비스 이용 약관에 동의해 주세요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    return true;
};

/**
 * @method
 * @name registerMember
 * @description register Member 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerMember = async function () {
    scwin.chrg_tel_no.setValue($c.util.getComponent('ipt_chrgTelNo1').getValue()+ "-" + $c.util.getComponent('ipt_chrgTelNo2').getValue()+ "-" + $c.util.getComponent('ipt_chrgTelNo3').getValue());
    scwin.encryp_cellphone_no.setValue($c.util.getComponent('ipt_encrypCellphoneNo1').getValue()+ "-" + $c.util.getComponent('ipt_encrypCellphoneNo2').getValue()+ "-" + $c.util.getComponent('ipt_encrypCellphoneNo3').getValue());
    scwin.chrg_fax_no.setValue($c.util.getComponent('ipt_chrgFaxNo1').getValue()+ "-" + $c.util.getComponent('ipt_chrgFaxNo2').getValue()+ "-" + $c.util.getComponent('ipt_chrgFaxNo3').getValue());
    $c.util.getComponent("ipt_chrgInnrNo").setValue($c.util.getComponent('ipt_chrgInnrNo1').getValue());
    if ($c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail1').getValue().trim()) > 0 && $c.str.getByteLength($c.util.getComponent('ipt_encrypChrgEmail2').getValue().trim()) > 0) {
        $c.util.getComponent("dma_searchMemberReq").set("encrypChrgEmail", $c.util.getComponent('ipt_encrypChrgEmail1').getValue()+ "@" + $c.util.getComponent('ipt_encrypChrgEmail2').getValue());
    }
    if (!await scwin.dataValidation()) {
        return;
    }
    if (!$c.str.isEmail($c.util.getComponent("dma_searchMemberReq").get("encrypChrgEmail"))) {
        await $c.win.alert("이메일 주소 형식이 아닙니다.");
        $c.util.getComponent("ipt_encrypChrgEmail1").focus();
        return;
    }
    await scwin.tx_fn_registerMember();
};

